import{_ as t,o as r,c as i,a2 as d}from"./chunks/framework.BS0bAV7E.js";const g=JSON.parse('{"title":"L1 guide: tui_ext.h - building UI from modules","description":"","frontmatter":{},"headers":[],"relativePath":"l1/tui-ext.md","filePath":"l1/tui-ext.md"}'),o={name:"l1/tui-ext.md"};function n(a,e,s,u,c,l){return r(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="l1-guide-tui-ext-h-building-ui-from-modules" tabindex="-1">L1 guide: tui_ext.h - building UI from modules <a class="header-anchor" href="#l1-guide-tui-ext-h-building-ui-from-modules" aria-label="Permalink to &quot;L1 guide: tui_ext.h - building UI from modules&quot;">​</a></h1><p><code>tui/tui_ext.h</code> is the TUI extension surface - 37 declarations in seven registries. All tables are static (freestanding kernel, no malloc dependency); registration returns 0 on success, -1 table full, -2 duplicate name/key. Every entry carries its owner (&quot;builtin&quot; for in-kernel pages) so unregister works.</p><h2 id="the-seven-registries" tabindex="-1">The seven registries <a class="header-anchor" href="#the-seven-registries" aria-label="Permalink to &quot;The seven registries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Registry</th><th>API</th><th>What it adds</th></tr></thead><tbody><tr><td>7.1 menu</td><td><code>tui_menu_register/unregister/list/sort</code></td><td>a launcher entry: label, desc, ASCII icon <code>[T]</code>, group, hotkey, priority, action callback</td></tr><tr><td>7.2 page</td><td><code>tui_page_register/unregister/list/render/input</code> + <code>tui_ext_page_main</code></td><td>a full page: render(win, scroll) + input(key) -&gt; 1 consumed; <code>tui_ext_page_main</code> is the generic runner</td></tr><tr><td>7.3 widget</td><td><code>tui_widget_register/unregister/list/render/event</code></td><td>a reusable widget type</td></tr><tr><td>7.4 command</td><td><code>tui_cmd_register/unregister/list/execute</code></td><td>a TUI command line hook; <code>tui_cmd_execute</code> returns fn&#39;s rc or -3 no-cmd</td></tr><tr><td>7.5 theme</td><td><code>tui_theme_register/unregister/list/set</code></td><td>colour themes</td></tr><tr><td>7.6 hotkey</td><td><code>tui_key_register/unregister/list/conflict</code></td><td>global hotkeys (conflict detection built in)</td></tr><tr><td>7.7 event</td><td><code>tui_event_register/unregister/list/dispatch</code></td><td>generic event subscribers</td></tr></tbody></table><p>Limits are named constants (<code>TUI_EXT_MENU_MAX 24</code>, <code>TUI_EXT_NAME_MAX 40</code>, ...) - bounded tables, refused loudly, never truncated.</p><h2 id="the-pattern-that-works" tabindex="-1">The pattern that works <a class="header-anchor" href="#the-pattern-that-works" aria-label="Permalink to &quot;The pattern that works&quot;">​</a></h2><p>Register on module init; unregister on teardown; the owner tag makes re-registration idempotent across module reloads. The CN TUI apps (<code>tui_cn_hw/net/sysinfo</code>) and the TUI command bridge are the two in-tree reference implementations - read one before writing yours.</p><h2 id="rendering" tabindex="-1">Rendering <a class="header-anchor" href="#rendering" aria-label="Permalink to &quot;Rendering&quot;">​</a></h2><p>Pages render through the same framebuffer primitives as the desktop (<code>tui_win</code> windows); <code>tui_page_render</code> receives the window and a scroll offset. Input: return 1 when your page consumed the key, 0 to let it bubble.</p>',9)])])}const _=t(o,[["render",n]]);export{g as __pageData,_ as default};
